/** "Agent Basic" -> "აგენტი Basic"; unknown names stay as they are. */
const licenseName = (name: string): string => LICENSE_NAMES_KA[name] ?? name

/** Template rules for strings the seed and `domain/billing.ts` build from parts. */
export const patterns: KaPattern[] = [
  /* ----------------------------------------------------- invoice lines */
  // "Agent Basic (AGENT_BASIC): 527 user-days / 31"
  [/^(.+?) \(([A-Z][A-Z0-9_]*)\): (\d+) user-days \/ (\d+)$/, (m) => `${licenseName(m[1])} (${m[2]}): ${m[3]} მომხმარებელი-დღე / ${m[4]}`],
  // "Points over the free allowance: 13 pts"
  [/^Points over the free allowance: (-?[\d.]+) pts$/, (m) => `უფასო ლიმიტზე მეტი ქულა: ${m[1]} ქულა`],
  // "Points credit: 3 pts"
  [/^Points credit: ([\d.]+) pts$/, (m) => `ქულების კრედიტი: ${m[1]} ქულა`],
  // "Project PRJ-301: Courier app click-to-call integration"
  [/^Project (PRJ-\d+): (.+)$/, (m) => `პროექტი ${m[1]}: ${workEntries[m[2]] ?? m[2]}`],

  /* ----------------------------------------------------- invoice notes */
  // "Replaces INV-2026-07-000006."
  [/^Replaces (INV-\d{4}-\d{2}-\d+)\.$/, (m) => `ანაცვლებს ინვოისს ${m[1]}.`],

  /* ---------------------------------------------------- outbox subject */
  [/^Invoice (INV-\d{4}-\d{2}-\d+) from Rigi$/, (m) => `Rigi-ს ინვოისი ${m[1]}`],
  [/^Reminder: invoice (INV-\d{4}-\d{2}-\d+) is overdue$/, (m) => `შეხსენება: ინვოისის ${m[1]} გადახდის ვადა გადაცილებულია`],
  [/^Invoice (INV-\d{4}-\d{2}-\d+) · (.+)$/, (m) => `ინვოისი ${m[1]} · ${m[2]}`],

  /* -------------------------------------------------------- system log */
  [/^Invoice (INV-\d{4}-\d{2}-\d+) disputed by the partner$/, (m) => `პარტნიორმა გაასაჩივრა ინვოისი ${m[1]}`],
]
